// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PricingPolicy) predicate.PricingPolicy {
	return predicate.PricingPolicy(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PricingPolicy) predicate.PricingPolicy {
	return predicate.PricingPolicy(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PricingPolicy) predicate.PricingPolicy {
	return predicate.PricingPolicy(sql.NotPredicates(p))
}
